// SPDX-License-Identifier: GPL-3.0-or-later
//! Licence texts compiled into every binary, so a single-file release carries them.

/// Chipload's own licence (GPL-3.0-or-later).
pub const LICENSE: &str = include_str!("../../../LICENSE");

/// Licences of every third-party crate in the release builds, generated by cargo-about
/// (`about.toml`); CI checks that it is up to date.
pub const THIRD_PARTY: &str = include_str!("../../../THIRD-PARTY-LICENSES.txt");

/// One-paragraph notice for About boxes and `--version`-style output.
pub fn short_notice() -> String {
    format!(
        "Chipload {} - 2.5D CAM.\nCopyright (C) 2026 Gustav Näslund.\n\
         This program is free software: you can redistribute it and/or modify it under the\n\
         terms of the GNU General Public License as published by the Free Software Foundation,\n\
         either version 3 of the License, or (at your option) any later version. It comes\n\
         with ABSOLUTELY NO WARRANTY. Always check the toolpath and do an air cut first.",
        env!("CARGO_PKG_VERSION")
    )
}
